  '#!/usr/bin/env bash\n# dreamfeed — v1 dreamwalking (docs/04): ambient repo-change delta injected\n# into the agent\'s context at turn boundaries.\n#\n#   dreamfeed init     install git producers + set cursor to current history\n#   dreamfeed emit …   append one event (called by git hooks and by the host)\n#   dreamfeed digest   print the UserPromptSubmit additionalContext JSON\n#   dreamfeed orient   print the SessionStart orientation JSON via gortex\n#\n# Design rules honored here (see docs/04 section 5): delta-since-cursor, never\n# replay; self-filter by author; hard cap per turn; zero-cost quiet turns.\n\nset -uo pipefail\n\nSTATE="${DREAMFEED_STATE:-$HOME/.local/state/t3-gortex-sandbox/dreamfeed}"\nEVENTS="$STATE/events.jsonl"\nCURSOR="$STATE/cursor"\nLOCK="$STATE/.lock"\nSELF="${DREAMFEED_SELF:-agent@sandbox.local}"\nWS="${DREAMFEED_WORKSPACE:-${T3_SANDBOX_WORKSPACE:-$HOME/workspace}}"\nCAP="${DREAMFEED_MAX_EVENTS:-12}"\n\n# The bus is advisory context, not a ledger of record: once it grows past\n# DREAMFEED_KEEP_LINES it is truncated to the newest DREAMFEED_TRIM_TO lines\n# and the cursor is pulled back by the same amount, so no event is ever\n# replayed after rotation.\nDREAMFEED_KEEP_LINES="${DREAMFEED_KEEP_LINES:-2000}"\nDREAMFEED_TRIM_TO="${DREAMFEED_TRIM_TO:-500}"\n\nline_count() {\n    wc -l <"$EVENTS" 2>/dev/null | tr -d \' \' || echo 0\n}\n\ninit() {\n    mkdir -p "$STATE"\n    : > "$LOCK" 2>/dev/null || true\n    [ -f "$EVENTS" ] || : > "$EVENTS"\n    line_count > "$CURSOR"\n\n    local hooks_dir="$WS/.git/hooks"\n    [ -d "$hooks_dir" ] || return 0\n\n    # The workspace is usually the HOST\'s repo mounted in, so these hooks land\n    # in the user\'s own .git/hooks. Never replace a hook someone else wrote:\n    # only (re)write files that are absent or carry our marker.\n    local h\n    for h in post-merge post-rewrite; do\n        # Hooks written before the marker existed are recognised by their body.\n        if [ -e "$hooks_dir/$h" ] \\\n            && ! grep -q -e \'^# dreamfeed-managed\' -e \'dreamfeed emit git commit\' "$hooks_dir/$h" 2>/dev/null; then\n            echo "dreamfeed: leaving existing $h hook alone (not dreamfeed-managed)" >&2\n            continue\n        fi\n        write_git_hook > "$hooks_dir/$h"\n        chmod +x "$hooks_dir/$h"\n    done\n}\n\n# One script serves both hooks. ORIG_HEAD is a REF that git sets before a\n# merge/pull/rebase moves HEAD -- it was previously read as "${ORIG_HEAD}", an\n# environment variable that is never set, so the fallback HEAD~1 made a\n# fast-forward pull of N commits report only the last one.\nwrite_git_hook() {\n    cat <<\'EOF\'\n#!/usr/bin/env bash\n# dreamfeed-managed: emits repo-change events for the agent (docs/04).\n# Safe to delete; `dreamfeed init` recreates it only if the file is absent.\nset -uo pipefail\n# The same .git/hooks is seen by the host\'s git when the workspace is a mount;\n# there is no dreamfeed out there, so do nothing.\ncommand -v dreamfeed >/dev/null 2>&1 || exit 0\n# post-rewrite after `commit --amend` rewrites the agent\'s own commit and does\n# not update ORIG_HEAD, so a range from it would be stale.\n[ "$(basename "$0")" = post-rewrite ] && [ "${1:-}" = amend ] && exit 0\nrange="HEAD~1..HEAD"\ngit rev-parse -q --verify ORIG_HEAD >/dev/null && range="ORIG_HEAD..HEAD"\ngit rev-list --no-merges "$range" 2>/dev/null | while read -r sha; do\n    author="$(git show -s --format=\'%ae\' "$sha")"\n    subject="$(git show -s --format=\'%s\' "$sha")"\n    f=()\n    while IFS= read -r p; do\n        [ -n "$p" ] && f+=("$p")\n    done < <(git diff --name-only "$sha^" "$sha" 2>/dev/null)\n    dreamfeed emit git commit "$author" "$sha" "$subject" ${f[@]+"${f[@]}"} || true\ndone\nEOF\n}\n\nemit() {\n    if [ $# -lt 5 ]; then\n        echo "usage: dreamfeed emit <source> <type> <author> <ref> <summary> [path...]" >&2\n        return 2\n    fi\n    local source_type="$1" kind="$2" author="$3" ref="$4" summary="$5"\n    shift 5\n\n    mkdir -p "$STATE"\n    : > "$LOCK" 2>/dev/null || true\n\n    (\n        flock 9\n\n        paths_json="$(printf \'%s\\n\' "$@" | jq -R . | jq -cs \'map(select(length>0))\')"\n        line="$(jq -cn \\\n            --arg ts "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \\\n            --arg s "$source_type" --arg t "$kind" --arg a "$author" \\\n            --arg r "$ref" --arg m "$summary" --argjson p "$paths_json" \\\n            \'{ts:$ts,source:$s,type:$t,author:$a,ref:$r,summary:$m,paths:$p}\')"\n        printf \'%s\\n\' "$line" >> "$EVENTS"\n\n        total="$(line_count)"\n        if [ "$total" -ge "$DREAMFEED_KEEP_LINES" ]; then\n            tail -n "$DREAMFEED_TRIM_TO" "$EVENTS" > "$EVENTS.trim"\n            mv "$EVENTS.trim" "$EVENTS"\n            # Cursor math after dropping the oldest `dropped` lines: an old\n            # event survives iff its index > dropped. Seen survivors are\n            # indices dropped+1 .. max(seen, dropped), so the new cursor (a\n            # count of seen lines from the top) is max(seen, dropped) - dropped.\n            # The just-appended last line always survives and is always unseen.\n            # (This used to store the UNSEEN count instead, which replayed\n            # already-digested events after every rotation.)\n            dropped=$((total - DREAMFEED_TRIM_TO))\n            seen="$(cat "$CURSOR" 2>/dev/null || echo 0)"\n            if [ "$seen" -gt "$dropped" ]; then base="$seen"; else base="$dropped"; fi\n            new_cursor=$((base - dropped))\n            [ "$new_cursor" -lt 0 ] && new_cursor=0\n            printf \'%s\\n\' "$new_cursor" > "$CURSOR"\n        fi\n    ) 9>"$LOCK"\n}\n\ndigest() {\n    [ -f "$EVENTS" ] || return 0\n    local total seen\n    total="$(line_count)"\n    seen="$(cat "$CURSOR" 2>/dev/null || echo 0)"\n\n    # Advance first: quiet turns cost nothing and never replay.\n    printf \'%s\\n\' "$total" > "$CURSOR"\n    [ "$total" -gt "$seen" ] || return 0\n\n    local new\n    new="$(tail -n +"$((seen + 1))" "$EVENTS" \\\n        | jq -c --arg self "$SELF" \'select(.author != $self)\')"\n    [ -n "$new" ] || return 0\n\n    local md count\n    md="$(printf \'%s\\n\' "$new" | head -n "$CAP" | jq -r \\\n        \'"- ["+.source+"/"+.type+"] "+(.ref[0:8])+" "+.summary+(if (.paths|length)>0 then "  ("+(.paths|join(", "))+")" else "" end)\')"\n    count="$(printf \'%s\\n\' "$new" | grep -c .)"\n    if [ "$count" -gt "$CAP" ]; then\n        md="$md"$\'\\n\'"…and $((count - CAP)) more."\n    fi\n\n    jq -cn --arg c "Repo changes since your last turn (not yours):"$\'\\n\'"$md" \\\n        \'{hookSpecificOutput:{hookEventName:"UserPromptSubmit",additionalContext:$c}}\'\n}\n\norient() {\n    local w\n    w="$(cd "$WS" 2>/dev/null && gortex wakeup 2>/dev/null)" || return 0\n    [ -n "$w" ] || return 0\n    jq -cn --arg c "Repo orientation (dreamwalking):"$\'\\n\'"$w" \\\n        \'{hookSpecificOutput:{hookEventName:"SessionStart",additionalContext:$c}}\'\n}\n\ncase "${1:-}" in\n    init)   init ;;\n    emit)   shift; emit "$@" ;;\n    digest) digest ;;\n    orient) orient ;;\n    *) echo "usage: dreamfeed {init|emit|digest|orient}" >&2; exit 2 ;;\nesac\n';

